import{_ as t,o,c as a,a0 as r}from"./chunks/framework.BQGW-Zpy.js";const p=JSON.parse('{"title":"ETHGlobal Lisbon 2026","description":"","frontmatter":{},"headers":[],"relativePath":"project/ethglobal-lisbon.md","filePath":"project/ethglobal-lisbon.md"}'),i={name:"project/ethglobal-lisbon.md"};function n(s,e,d,c,h,l){return o(),a("div",null,[...e[0]||(e[0]=[r('<h1 id="ethglobal-lisbon-2026" tabindex="-1">ETHGlobal Lisbon 2026 <a class="header-anchor" href="#ethglobal-lisbon-2026" aria-label="Permalink to &quot;ETHGlobal Lisbon 2026&quot;">​</a></h1><p>F2F Cross-Border was extended past the original UZH submission (see <a href="./uzh-blockchain.html">UZH Blockchain</a> for that phase) to also enter <strong>ETHGlobal Lisbon 2026</strong>, under the <strong>Continuity Track</strong> (&quot;Ship a Feature&quot;, extending an existing project rather than starting fresh) and targeting two bounties:</p><ul><li><strong>No Solidity Allowed</strong> — the entire settlement, anchoring, and completion layer runs on Hedera&#39;s native services (HCS, HTS, HSS), with no Solidity contracts anywhere in the flow.</li><li><strong>Autonomous On-Chain Automation Platform</strong> (Continuity-only) — met by the Hedera Schedule Service (HSS) completion anchor, described below, which is genuinely autonomous: once both required signatures land, Hedera&#39;s own consensus executes the message submission with no further code of ours involved.</li></ul><h2 id="what-was-added-for-this-submission" tabindex="-1">What was added for this submission <a class="header-anchor" href="#what-was-added-for-this-submission" aria-label="Permalink to &quot;What was added for this submission&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Addition</th><th>What it does</th></tr></thead><tbody><tr><td><strong>HSS-gated completion anchor</strong></td><td>A fourth anchor (<code>scheduleAnchor.mjs</code>), beyond the original compliance/quote/routing anchors, that only reaches HCS once both the source-side and destination-side partner have independently signed a <code>ScheduleCreateTransaction</code></td></tr><tr><td><strong>2-of-2 threshold-key intermediary account</strong></td><td><code>thresholdAccount.mjs</code>, a Hedera account whose <code>KeyList</code> requires both partner keys to move funds, so no single party (including the platform) holds unilateral control</td></tr><tr><td><strong>Dedicated completion topic</strong></td><td>A second HCS topic whose submit key is the same 2-of-2 <code>KeyList</code>, so the two-party requirement is enforced at the protocol level, not just in application code</td></tr><tr><td><strong>How It Works page</strong></td><td>A new <code>/how-it-works</code> route walking through a full Portugal → Armenia corridor end to end, with every anchor point marked, plus a horizontal backend-call map</td></tr><tr><td><strong>SaucerSwap liquidity source</strong></td><td>Hedera stablecoin liquidity depth checks now call SaucerSwap&#39;s own <code>/stats</code> endpoint directly, a named Hedera ecosystem partner, in place of a third-party aggregator</td></tr></tbody></table><h2 id="why-this-fits-the-continuity-track" tabindex="-1">Why this fits the Continuity Track <a class="header-anchor" href="#why-this-fits-the-continuity-track" aria-label="Permalink to &quot;Why this fits the Continuity Track&quot;">​</a></h2><p>The base project (compliance/quote/routing anchoring, corridor routing, licensed-partner settlement) already existed from the UZH submission. Everything above is additive: a new capability (HSS automation) layered onto the existing settlement flow, a new page that walks through it, and a swap of one data source for a more first-party one, none of it a rewrite of the original architecture.</p><h2 id="where-each-piece-lives" tabindex="-1">Where each piece lives <a class="header-anchor" href="#where-each-piece-lives" aria-label="Permalink to &quot;Where each piece lives&quot;">​</a></h2><ul><li>Track/bounty fit: this page</li><li>Technical detail on the completion anchor and threshold account: <a href="./../architecture/trust-layer.html#the-completion-anchor-gated-by-two-parties-not-one">The Trust Layer</a></li><li>Module-level reference: <a href="./../reference/modules.html"><code>scheduleAnchor.mjs</code>, <code>thresholdAccount.mjs</code>, <code>topic.mjs</code></a></li><li>User-facing walkthrough: <code>/how-it-works</code> (<code>HowItWorks.jsx</code>, embedding <code>use-case-story.html</code>)</li></ul>',9)])])}const m=t(i,[["render",n]]);export{p as __pageData,m as default};
